'use strict';
// Shared scripted text/voice UX. No model, upload, microphone or API request runs here.
const aiTextChats=new Map();let aiTextSequence=0,aiTextGeneration=0;
function isAiChatScreen(name=current){return ['AI chat','AI chat · trial','AI chat · attachment','Voice'].includes(name);}
function aiTextKey(){if(current==='AI chat · attachment')return 'image';return current==='AI chat · trial'?'trial':current==='Voice'?'voice':'standard';}
function aiTextSession(){const key=aiTextKey();if(!aiTextChats.has(key)){const trial=key==='trial',draft=trial?{id:'ai-text-'+(++aiTextSequence),name:'Spotify',price:'11.99',currency:'USD',cycle:'Monthly',category:'Entertainment',start:'2026-10-24',trialDays:7,trialDuration:'7 days',trialEnd:'2026-10-31',trialEndSource:'exact',autoRenew:true,renewal:'2026-10-31'}:{id:'ai-text-'+(++aiTextSequence),name:'Duolingo',price:'9.99',currency:'USD',cycle:'Monthly',category:'Education',renewal:'2026-11-20',start:'',note:''};aiTextChats.set(key,{draft,messages:[{id:1,role:'user',...(key==='voice'?{kind:'voice',audio:aiVoiceMetadata('voice-seed-'+draft.id)}:{}),text:trial?'Spotify is USD 11.99 monthly after a 7-day trial that started on 24 October 2026. Track renewals after the trial.':'I pay USD 9.99 monthly for Duolingo. My next renewal is 20 November 2026.'},{id:2,role:'assistant',text:'Your subscription is ready. Tell me if anything needs changing.'}],input:'',thinking:false,saving:false,saved:false,failNext:false,showNew:false,nearBottom:true,timer:null,invalidCorrection:false});}const session=aiTextChats.get(key);if(key==='image'&&!session.imageInitialized){session.imageInitialized=true;session.draft=null;session.messages=[{id:1,role:'assistant',text:'Share an image or PDF receipt, invoice or bank statement. I’ll help you review subscriptions to track.'}];session.image=null;}return session;}
function aiValidDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value;}
function aiTextMissing(d){if(!d.name)return 'name';if(d.platformNeedsReview)return 'platform-name';if(d.matchNeedsReview)return 'existing-plan';if(d.price===undefined||d.price===null||String(d.price).trim()===''||!Number.isFinite(Number(d.price))||Number(d.price)<=0)return 'price';if(!d.currency)return 'currency';if(d.priceNeedsReview)return 'observed-price';if(!d.cycle)return 'cycle';if(d.trialDays){if(!aiValidDate(d.start))return 'start';if(!aiValidDate(d.trialEnd))return 'trialEnd';}else if(!aiValidDate(d.renewal))return 'renewal';return '';}
function aiMissingQuestion(field,draft={}){if(field==='platform-name')return 'Which subscription service is this? Tell me its name, or confirm the displayed name below.';if(field==='existing-plan')return 'Review the matching subscriptions below. Is this an existing plan or a separate one?';if(field==='observed-price')return 'The statement shows '+(draft.observedCurrency||draft.currency)+' '+(draft.observedAmount||draft.price)+'. Should I track this amount? You can confirm with “yes” or tell me the correct amount.';return ({name:'Which platform or service is this for?',price:'How much does it cost? For a trial, tell me the price after the trial.',currency:'Which currency is that amount in?',cycle:'How often are you billed—weekly, monthly, quarterly or yearly?',start:'What date did the trial start? Include the day, month and year.',trialEnd:'When does the trial end? Include the full date.',renewal:'What is the next renewal date? Include the day, month and year.'})[field]||'';}
function aiParseText(text,original){const draft={...original},normalized=text.trim(),note=normalized.match(/^notes?\s*[:=-]?\s+(.+)$/i);let changed=false;if(['image','pdf'].includes(draft.inputMode)&&draft.platformNeedsReview&&typeof manualServices!=='undefined'){const service=manualServices.find(entry=>aiNormalizeMerchant(entry[0])===aiNormalizeMerchant(normalized.replace(/^(service|platform|name)(?: is|:)?\s+/i,'')));if(service){draft.name=service[0];changed=true;}}if(draft.priceNeedsReview&&/^(yes|confirm|use this amount)[.!]?$/i.test(normalized)){draft.priceNeedsReview=false;changed=true;}if(note){draft.note=note[1].slice(0,500);return {draft,changed:true,reply:'Note updated.'};}
 const platform=normalized.match(/\b(Netflix|Spotify|Duolingo|Figma|Notion|iCloud\+)(?=\s|$|[.,!?])/i),newIntent=/\b(add|track|create)\b/i.test(normalized);if(newIntent&&!platform)return {draft:original,changed:false,reply:'Which service would you like to add? Send its name and billing details.'};if(platform&&!newIntent){const name=platform[1].toLowerCase()==='icloud+'?'iCloud+':platform[1][0].toUpperCase()+platform[1].slice(1).toLowerCase();if(draft.name!==name)draft.category='';draft.name=name;changed=true;}if(platform&&newIntent){const name=platform[1].toLowerCase()==='icloud+'?'iCloud+':platform[1][0].toUpperCase()+platform[1].slice(1).toLowerCase();Object.keys(draft).forEach(key=>delete draft[key]);Object.assign(draft,{id:original.id,name,note:'',start:''});changed=true;}
 const currency=normalized.match(/\b(USD|EUR|GBP|PKR|AED|INR)\b/i);if(currency){draft.currency=currency[1].toUpperCase();changed=true;}
 const money=normalized.match(/\b(?:USD|EUR|GBP|PKR|AED|INR)\s*(\d+(?:\.\d{1,2})?)/i)||normalized.match(/(\d+(?:\.\d{1,2})?)\s*(?:USD|EUR|GBP|PKR|AED|INR)\b/i)||normalized.match(/\b(?:amount|price|cost|pay)\s*(?:is\s+|to\s+)?[$€£]?\s*(\d+(?:\.\d{1,2})?)/i)||normalized.match(/^[$€£]?(\d+(?:\.\d{1,2})?)$/);if(money){draft.price=Number(money[1]).toFixed(2);if(draft.priceNeedsReview!==undefined)draft.priceNeedsReview=false;changed=true;}
 const cycle=normalized.match(/\b(weekly|monthly|quarterly|yearly|annually)\b/i);if(cycle){draft.cycle=cycle[1].toLowerCase()==='annually'?'Yearly':cycle[1][0].toUpperCase()+cycle[1].slice(1).toLowerCase();changed=true;}
 let date=normalized.match(/\b(\d{4}-\d{2}-\d{2})\b/)?.[1];if(!date){const named=normalized.match(/\b(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})\b/i);if(named){const month=['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(named[2].toLowerCase())+1;date=named[3]+'-'+String(month).padStart(2,'0')+'-'+named[1].padStart(2,'0');}}
 if(!date&&/^(?:next\s+)?(?:renewal|start|trial\s+ends?|date)\b/i.test(normalized))return {draft:original,changed:false,invalid:true,reply:'Please include a full date, such as 20 November 2026.'};if(date){if(!aiValidDate(date))return {draft:original,changed:false,invalid:true,reply:'That date doesn’t look valid. Please use a full date, such as 20 November 2026.'};if(/\bstart(?:ed)?\b/i.test(normalized)){draft.start=date;if(draft.trialDays){draft.trialEnd=plusDays(date,draft.trialDays);draft.trialEndSource='calculated';draft.renewal=draft.trialEnd;}}else if(/trial\s+ends?/i.test(normalized)){draft.trialEnd=date;draft.trialEndSource='exact';draft.renewal=date;}else draft.renewal=date;changed=true;}
 const days=normalized.match(/\b(\d+)\s*[- ]?day(?:s)?\s+trial\b/i)||normalized.match(/\btrial\s+(\d+)\s+days\b/i);if(days){const n=Number(days[1]);if(n<1||n>365)return {draft:original,changed:false,invalid:true,reply:'Tell me a trial duration between 1 and 365 days.'};draft.trialDays=n;draft.trialDuration=n+' days';draft.autoRenew=draft.autoRenew!==false;if(aiValidDate(draft.start)){draft.trialEnd=plusDays(draft.start,n);draft.trialEndSource='calculated';draft.renewal=draft.trialEnd;}changed=true;}
 if(/auto[- ]?renew(?:al)?\s+(?:off|no)/i.test(normalized)){draft.autoRenew=false;changed=true;}else if(/auto[- ]?renew(?:al)?\s+(?:on|yes)/i.test(normalized)){draft.autoRenew=true;changed=true;}
 if(!draft.category&&draft.name)draft.category=({Duolingo:'Education',Figma:'Productivity',Notion:'Productivity','iCloud+':'Storage'})[draft.name]||'Entertainment';if(['image','pdf'].includes(draft.inputMode)&&typeof aiGroundAttachmentDraft==='function')Object.assign(draft,aiGroundAttachmentDraft(draft,typeof allTrackedRecords==='function'?allTrackedRecords():[],typeof manualServices!=='undefined'?manualServices:[]));const missing=aiTextMissing(draft);return {draft,changed,reply:missing?aiMissingQuestion(missing,draft):changed?'Updated. Check the details below before adding it.':'What would you like to change—the amount, billing cycle, renewal date or a note?'};
}
function aiTextIcon(kind){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({attach:'<path d="m8 12 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9"/><path d="m7 13 7-7"/>',voice:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11v1a7 7 0 0 0 14 0v-1M12 19v3M8 22h8"/>',send:'<path d="M12 19V5m-6 6 6-6 6 6"/>',down:'<path d="M12 5v14m-6-6 6 6 6-6"/>'})[kind]}</svg>`;}
function aiTextCard(session){
 if(!session.draft)return '';const d=session.draft,missing=aiTextMissing(d),trial=!!d.trialDays;
 const readiness=session.saved?'Added to your subscriptions':session.image||session.imageLoading?'Send your image first':session.thinking?'Updating details…':session.voiceDraft||session.voiceRecording?'Finish your voice message':session.messages.some(m=>m.failed)?'Retry your last message':session.invalidCorrection?'Check your last correction':d.matchNeedsReview?'Review existing plans':missing?'A few details to finish':'Ready to add';
 const fields=[[trial?'Trial ends':'Next renewal',aiValidDate(trial?d.trialEnd:d.renewal)?detailDate(trial?d.trialEnd:d.renewal):'Date needed']];
 if(d.category)fields.push(['Category',d.category]);
 if(aiValidDate(d.start)||trial)fields.push(['Start date',aiValidDate(d.start)?detailDate(d.start):'Date needed']);
 if(trial)fields.push(['Trial duration',d.trialDays+' days'],['Auto-renew tracking',d.autoRenew===false?'Off':'On']);
 if(d.sourceKind==='statement'){fields.push(['Observed charge',(d.observedCurrency||d.currency)+' '+(d.observedAmount||d.price)+' · '+detailDate(d.observedDate)],['Billing cycle',d.cycle||'Needs confirmation']);}if(d.inputMode==='pdf')fields.push(['Source',(d.sourceKind==='statement'?'Bank statement':'PDF receipt')+(d.evidencePage?' · page '+d.evidencePage:'')]);const hasPrice=d.price!==undefined&&d.price!==null&&String(d.price).trim()!==''&&Number.isFinite(Number(d.price));
 return `<section class="ai-draft-card" aria-label="Subscription draft"><header><span class="ai-draft-platform">${platformLogo(d.name||'Unknown')}</span><div class="ai-draft-identity"><strong>${escape(d.name||'Your subscription')}</strong><small>${session.saved?'✓ ':''}${readiness}</small></div><div class="ai-draft-price"><strong>${hasPrice?(d.currency?escape(d.currency)+' ':'')+Number(d.price).toFixed(2):'Amount needed'}</strong><span>${d.sourceKind==='statement'&&d.priceNeedsReview?'Observed charge':(trial?'After trial · ':'')+escape(d.cycle||'Cycle needed')}</span>${hasPrice&&!d.currency?'<small>Currency needed</small>':''}</div></header><dl class="ai-draft-grid">${fields.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>${d.note?.trim()?`<div class="ai-draft-note"><span>Notes</span><p>${escape(d.note)}</p></div>`:''}<button class="primary" data-ai-text-add ${missing||session.thinking||session.saving||session.saved||session.image||session.imageLoading||session.voiceDraft||session.voiceRecording||session.invalidCorrection||session.messages.some(m=>m.failed)?'disabled':''}>${session.saved?'Added ✓':session.saving?'Adding…':'Add subscription'}</button>${session.saved?'<button class="ai-open-saved" data-ai-text-open>View subscription ›</button>':''}</section>`;
}
function aiTextMessages(session){return session.messages.map(m=>`<div class="ai-message-wrap ai-message-${m.role}"><span class="ai-message-author">${m.role==='assistant'?'Loop':'You'}</span><div class="ai-message-bubble">${m.kind==='voice'?aiVoiceMessage(m.audio):m.kind==='image'?aiImageMessage(m):escape(m.text)}</div>${m.failed&&m.kind==='image'?aiImageFailure(m):m.failed?`<div class="ai-message-failure" role="status">Couldn’t send. <button data-ai-text-retry="${m.id}">Retry</button></div>`:''}</div>`).join('')+(session.thinking?`<div class="ai-thinking" role="status" aria-label="${session.imageProcessing?(session.attachmentProcessingKind==='pdf'?'Reading PDF':'Reading image'):'Loop is thinking'}"><span>${session.imageProcessing?(session.attachmentProcessingKind==='pdf'?'Reading PDF':'Reading image'):'Thinking'}</span><i aria-hidden="true"></i><i aria-hidden="true"></i><i aria-hidden="true"></i></div>`:'')+aiImageCandidateTabs(session)+aiAttachmentMatchNotice(session)+aiTextCard(session);}
function aiChatHeader(){return `<header class="ai-chat-header">${backButton({attributes:`data-ai-chat-back`,label:"Go back",className:""})}<div><h2>Loop</h2><span>Your subscription assistant</span></div><img src="assets/renewless-mark.svg" alt=""></header>`;}
function aiChatComposer(session){if(session.voiceRecording)return aiRecordingComposer(session);return `<form class="ai-text-composer" data-ai-text-composer>${aiImagePreview(session)}<input type="file" data-ai-image-file accept="image/png,image/jpeg,image/webp" hidden aria-hidden="true" tabindex="-1"><input type="file" data-ai-pdf-file accept="application/pdf,.pdf" hidden aria-hidden="true" tabindex="-1"><label class="sr-only" for="ai-text-input">Message Loop</label><div class="ai-composer-frame"><textarea id="ai-text-input" name="message" rows="1" placeholder="${session.image?'Add a note…':'Message Loop…'}" maxlength="2000" enterkeyhint="send">${escape(session.input)}</textarea><div class="ai-composer-actions"><button type="button" class="ai-idle-icon" data-ai-text-later="attachment" aria-label="Attach a file">${aiTextIcon('attach')}</button><button type="button" class="ai-idle-icon" data-ai-text-later="voice" data-ai-hold-mic aria-label="Hold to record voice message. Release to send. Slide left to cancel." title="Hold to record · release to send">${aiTextIcon('voice')}</button><button class="ai-send-icon" type="submit" aria-label="Send message" hidden>${aiTextIcon('send')}</button></div></div></form>`;}
function aiTextScreen(){const session=aiTextSession();return `<div class="ai-chat-shell">${aiChatHeader()}<div class="sr-only" data-ai-text-announcement role="status"></div><div class="ai-message-area" aria-label="Conversation with Loop" tabindex="0">${aiTextMessages(session)}</div><button class="ai-new-message" data-ai-text-bottom hidden>New message ${aiTextIcon('down')}</button>${aiChatComposer(session)}</div>`;}
function aiSyncComposer(){if(!isAiChatScreen())return;const session=aiTextSession(),field=document.querySelector('#ai-text-input');if(!field){syncAiVoiceComposer(session);return;}const hasText=!!field.value.trim()||!!session.image;document.querySelectorAll('.ai-idle-icon').forEach(el=>el.hidden=hasText);const send=document.querySelector('.ai-send-icon');send.hidden=!hasText;send.disabled=session.thinking||session.saving||session.imageLoading||session.messages.some(m=>m.failed);const attach=document.querySelector('[data-ai-text-later="attachment"]');if(attach)attach.disabled=send.disabled;const mic=document.querySelector('[data-ai-hold-mic]');if(mic)mic.disabled=send.disabled;const area=document.querySelector('.ai-message-area'),atBottom=area.scrollHeight-area.clientHeight-area.scrollTop<60;field.style.height='auto';field.style.height=Math.min(field.scrollHeight,96)+'px';document.querySelector('.ai-chat-shell').style.setProperty('--ai-composer-height',document.querySelector('.ai-text-composer').offsetHeight+'px');if(atBottom)area.scrollTop=area.scrollHeight;}
function aiRefreshConversation(session,scroll=false,incoming=false){if(aiTextSession()!==session)return;const area=document.querySelector('.ai-message-area');if(!area)return;const y=area.scrollTop,atBottom=area.scrollHeight-area.clientHeight-y<60;area.innerHTML=aiTextMessages(session);initAiVoicePlayers(session);if(scroll||atBottom){area.scrollTop=area.scrollHeight;session.showNew=false;}else{area.scrollTop=y;session.showNew=session.showNew||incoming;}document.querySelector('.ai-new-message').hidden=!session.showNew;const announcement=document.querySelector('[data-ai-text-announcement]');if(announcement&&!session.thinking)announcement.textContent=session.messages.some(m=>m.failed)?(session.messages.findLast(m=>m.failed&&m.errorKind)?.failureText||'Message could not be sent. Retry is available.'):session.messages.filter(m=>m.role==='assistant').at(-1)?.text||'';aiSyncComposer();}
function aiSendText(text,retryId,voice){const session=aiTextSession();text=text.trim();if(!text||session.thinking||session.saving||session.imageLoading)return;if(session.imageError){session.imageError='';document.querySelector('.ai-image-validation')?.remove();}let message;if(retryId){message=session.messages.find(m=>m.id===retryId&&m.failed);if(!message)return;message.failed=false;}else{if(session.messages.some(m=>m.failed))return;message={id:Date.now(),role:'user',text,...(voice?{kind:'voice',audio:voice}:{})};session.messages.push(message);if(!voice){session.input='';document.querySelector('#ai-text-input').value='';}}session.thinking=true;aiRefreshConversation(session,!retryId);const generation=aiTextGeneration,forceFailure=session.failNext;session.failNext=false;document.querySelector('[data-ai-text-failure]')?.setAttribute('aria-pressed','false');clearTimeout(session.timer);session.timer=setTimeout(()=>{if(generation!==aiTextGeneration||![...aiTextChats.values()].includes(session))return;session.thinking=false;if(forceFailure)message.failed=true;else{const voiceNew=message.kind==='voice'&&session.draft.name!=='Duolingo',newIntent=voiceNew||(/\b(add|track|create)\b/i.test(text)&&/\b(Netflix|Spotify|Duolingo|Figma|Notion|iCloud\+)(?=\s|$|[.,!?])/i.test(text));if(session.saved&&!newIntent)session.messages.push({id:Date.now()+1,role:'assistant',text:'This subscription is already added. Open it to edit the saved details.'});else{const original=newIntent||!session.draft?{...(voiceNew?{}:session.draft),id:'ai-text-'+(++aiTextSequence)}:session.draft,result=aiParseText(text,original);session.draft=result.draft;if(result.invalid)session.invalidCorrection=true;else if(result.changed)session.invalidCorrection=false;if(newIntent)session.saved=false;session.messages.push({id:Date.now()+1,role:'assistant',text:result.reply});}}if(isAiChatScreen()&&aiTextSession()===session)aiRefreshConversation(session,false,true);},1500);}
function aiTextAfterRender(){aiAttachmentAfterRender(isAiChatScreen()?aiTextSession():null);document.getElementById('ai-text-inspection')?.remove();if(!isAiChatScreen()){cancelAiVoiceRecording();pauseAiVoicePlayers();return;}const session=aiTextSession();syncAiRecordingContext(session);initAiVoicePlayers(session);document.querySelector('[data-variant=upgraded] .variant-title h2').textContent='Final';document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent=(current==='AI chat · attachment'?'Attachment design preview · ':'Final AI text/voice design · approved 31 Oct 2026. ')+'Scripted AI and local saves. Voice playback uses bundled fictional speech; hold the mic to record, release to send; slide left to cancel. The timer/voice are simulated and use fictional speech. No microphone access, real transcription or upload. Images/PDFs stay local; the external image examples simulate extraction. Personal files can be previewed but analysis is unavailable in this prototype. Try “amount 12.99” to correct the draft.';document.querySelector('.footnote').textContent='Fictional conversation and local draft/save only. Real AI extraction, network failures, authentication and persistence need separate integration.';document.getElementById('context').insertAdjacentHTML('afterend',`<div class="ai-text-inspection" id="ai-text-inspection"><button data-ai-text-reset>Reset conversation</button><button data-ai-image-example="single">Example receipt</button><button data-ai-image-example="multi">Two plans</button><button data-ai-image-example="unclear">Unclear image</button><button data-ai-image-example="pdf">Receipt PDF</button><button data-ai-image-example="statement">Bank statement</button><button data-ai-image-example="protected">Protected PDF outcome</button><button data-ai-text-failure aria-pressed="${session.failNext}">Fail next send</button></div>`);aiSyncComposer();const area=document.querySelector('.ai-message-area');area.scrollTop=area.scrollHeight;area.addEventListener('scroll',()=>{session.nearBottom=area.scrollHeight-area.clientHeight-area.scrollTop<60;if(session.nearBottom){session.showNew=false;document.querySelector('.ai-new-message').hidden=true;}});}
document.addEventListener('input',e=>{if(e.target.id==='ai-text-input'){aiTextSession().input=e.target.value;aiSyncComposer();}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-ai-text-composer]'))return;e.preventDefault();if(aiTextSession().image)aiSendImage();else aiSendText(e.target.elements.message.value);});
document.addEventListener('keydown',e=>{if(e.target.id==='ai-text-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(aiTextSession().image)aiSendImage();else aiSendText(e.target.value);}});
document.addEventListener('click',e=>{const retry=e.target.closest('[data-ai-text-retry]'),later=e.target.closest('[data-ai-text-later]');if(retry){const message=aiTextSession().messages.find(m=>m.id===Number(retry.dataset.aiTextRetry));if(message?.kind==='image')aiSendImage(message.id);else if(message)aiSendText(message.text,message.id);return;}if(later){if(later.dataset.aiTextLater==='voice'){if(e.detail===0)toast('Hold the microphone to record. Release to send.');}else aiPickImage();return;}if(e.target.closest('[data-ai-chat-back]')){cancelAiVoiceRecording();pauseAiVoicePlayers();go('back');return;}if(e.target.closest('[data-ai-text-bottom]')){const area=document.querySelector('.ai-message-area');area.scrollTop=area.scrollHeight;aiTextSession().showNew=false;document.querySelector('.ai-new-message').hidden=true;return;}if(e.target.closest('[data-ai-text-failure]')){const session=aiTextSession();session.failNext=!session.failNext;e.target.closest('button').setAttribute('aria-pressed',String(session.failNext));return;}if(e.target.closest('[data-ai-text-reset]')){cancelAiVoiceRecording();disposeAiVoiceSession(aiTextSession());disposeAiImages(aiTextSession());clearTimeout(aiTextSession().timer);aiTextChats.delete(aiTextKey());render();return;}if(e.target.closest('[data-ai-text-open]')){const record=allTrackedRecords().find(r=>r.id===aiTextSession().draft.id);if(record)openCalendarRecord(record);else toast('This subscription is no longer available.');return;}if(e.target.closest('[data-ai-text-add]')){const session=aiTextSession();if(session.saved||session.thinking||session.saving||session.image||session.imageLoading||session.messages.some(m=>m.failed)||session.voiceDraft||session.voiceRecording||session.invalidCorrection||aiTextMissing(session.draft))return;session.saving=true;aiRefreshConversation(session);const generation=aiTextGeneration,record=['image','pdf'].includes(session.draft.inputMode)?aiAttachmentRecord(session.draft,previewLoginEmail):{...session.draft,source:'AI',creatorEmail:previewLoginEmail,inboxEmail:previewLoginEmail};setTimeout(()=>{if(generation!==aiTextGeneration||![...aiTextChats.values()].includes(session))return;trialRecords.set(record.id,record);session.saved=true;session.saving=false;aiRememberImageCandidate(session);if(isAiChatScreen()&&aiTextSession()===session){openCalendarRecord(record);toast('Subscription added.');}},500);}});

function resetAiTextChats(){cancelAiVoiceRecording(null);clearAiVoicePlayers();aiTextGeneration++;for(const session of aiTextChats.values()){clearTimeout(session.timer);disposeAiImages(session);}aiTextChats.clear();}
